import { useSelector } from '@xstate/react';
import { useRouter } from 'next/router';
import { useMemo, useState } from 'react';
import * as icons from './Icons';
import { metadata, MetadataItem } from './metadata';
import { ModalsMachineInterpreter } from './modalsMachine';

const entries: (MetadataItem & { id: string })[] = Object.entries(metadata).map(
  ([id, value]) => ({
    ...value,
    id,
  }),
);

export const CatalogueSearcher = (props: {
  service: ModalsMachineInterpreter;
}) => {
  const input = useSelector(
    props.service,
    (state) => state.context.searchModalText,
  );
  const optionsToShow = useMemo(() => {
    const search = new RegExp(input, 'i');
    return entries
      .filter((entry) => {
        return search.test(entry.title);
      })
      .slice(0, 5);
  }, [input]);

  const router = useRouter();

  return (
    <div className="flex flex-col w-full bg-white">
      <div className="p-6 border-b">
        <div className="flex items-center px-4 pr-2 space-x-2 group focus-within:ring">
          <icons.SearchOutlined className="text-gray-400" />
          <input
            aria-label="Search"
            type="search"
            onChange={(e) => {
              props.service.send({
                type: 'UPDATE_SEARCH_MODAL_TEXT',
                text: e.target.value,
              });
            }}
            value={input}
            placeholder="Search for machines..."
            id="search"
            className="py-2 text-base text-gray-600 w-72 focus:outline-none"
            autoComplete="off"
          ></input>
          <div className="px-2 py-1 text-xs text-gray-400 border border-gray-300 rounded">
            ESC
          </div>
        </div>
      </div>
      <ul className="p-6 py-4">
        {optionsToShow.map((option) => {
          const Icon = icons[option.icon];
          return (
            <li key={option.id}>
              <button
                onClick={() => {
                  router.push(`/machines/${option.id}`);
                  props.service.send('CLOSE');
                }}
                className="flex items-center w-full px-3 py-3 space-x-3 focus:outline-none focus:ring"
              >
                <Icon className="flex-shrink-0 block text-gray-500 fill-current" />
                <span className="block text-sm text-gray-600">
                  {option.title}
                </span>
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
};

import { assign, createMachine } from 'xstate';

export interface MultiStepFormMachineContext {
  beneficiaryInfo?: BeneficiaryInfo;
  dateInfo?: DateInfo;
  errorMessage?: string;
}

interface BeneficiaryInfo {
  name: string;
  amount: number;
  currency: string;
}

interface DateInfo {
  preferredData: string;
}

export type MultiStepFormMachineEvent =
  | {
      type: 'BACK';
    }
  | {
      type: 'CONFIRM_BENEFICIARY';
      info: BeneficiaryInfo;
    }
  | {
      type: 'CONFIRM_DATE';
      info: DateInfo;
    }
  | {
      type: 'CONFIRM';
    };

const multiStepFormMachine = createMachine<
  MultiStepFormMachineContext,
  MultiStepFormMachineEvent
>(
  {
    id: 'multiStepFormWithValidation',
    initial: 'enteringBeneficiary',
    states: {
      enteringBeneficiary: {
        initial: 'idle',
        id: 'enteringBeneficiary',
        onDone: {
          target: 'enteringDate',
        },
        states: {
          idle: {
            exit: ['clearErrorMessage'],
            on: {
              CONFIRM_BENEFICIARY: {
                target: 'submitting',
                actions: ['assignBeneficiaryInfoToContext'],
              },
            },
          },
          submitting: {
            invoke: {
              src: 'validateBeneficiary',
              onDone: {
                target: 'complete',
              },
              onError: {
                target: 'idle',
                actions: 'assignErrorMessageToContext',
              },
            },
          },
          complete: { type: 'final' },
        },
      },
      enteringDate: {
        id: 'enteringDate',
        onDone: {
          target: 'confirming',
        },
        initial: 'idle',
        states: {
          idle: {
            exit: ['clearErrorMessage'],
            on: {
              CONFIRM_DATE: {
                target: 'submitting',
                actions: ['assignDateToContext'],
              },
              BACK: {
                target: '#enteringBeneficiary',
              },
            },
          },
          submitting: {
            invoke: {
              src: 'validateDate',
              onDone: {
                target: 'complete',
              },
              onError: {
                target: 'idle',
                actions: 'assignErrorMessageToContext',
              },
            },
          },
          complete: { type: 'final' },
        },
      },
      confirming: {
        onDone: {
          target: 'success',
        },
        initial: 'idle',
        states: {
          idle: {
            exit: ['clearErrorMessage'],
            on: {
              CONFIRM: 'submitting',
              BACK: {
                target: '#enteringDate',
              },
            },
          },
          submitting: {
            invoke: {
              src: 'submitPayment',
              onDone: {
                target: 'complete',
              },
              onError: {
                target: 'idle',
                actions: 'assignErrorMessageToContext',
              },
            },
          },
          complete: { type: 'final' },
        },
      },
      success: {
        type: 'final',
      },
    },
  },
  {
    actions: {
      assignDateToContext: assign((context, event) => {
        if (event.type !== 'CONFIRM_DATE') return {};
        return {
          dateInfo: event.info,
        };
      }),
      clearErrorMessage: assign({
        errorMessage: undefined,
      }),
      assignBeneficiaryInfoToContext: assign((context, event) => {
        if (event.type !== 'CONFIRM_BENEFICIARY') return {};
        return {
          beneficiaryInfo: event.info,
        };
      }),
      assignErrorMessageToContext: assign((context, event: any) => {
        return {
          errorMessage: event.data?.message || 'An unknown error occurred',
        };
      }),
    },
  },
);

export default multiStepFormMachine;

import { assign, createMachine } from 'xstate';

export interface WithLocalCacheMachineContext {
  cache: Cache;
  errorMessage?: string;
  currentVariablesBeingProcessed?: Variables;
}

type Cache = Record<string, Data>;

interface Variables {
  id: string;
}

interface Data {
  name: string;
}

export type WithLocalCacheMachineEvent =
  | {
      type: 'FETCH';
      variables: Variables;
    }
  | {
      type: 'RECEIVE_DATA';
      data: Data;
    }
  | {
      type: 'CANCEL';
    };

const withLocalCacheMachine = createMachine<
  WithLocalCacheMachineContext,
  WithLocalCacheMachineEvent
>(
  {
    id: 'simpleDataFetch',
    initial: 'idle',
    context: {
      cache: {},
    },
    states: {
      idle: {
        on: {
          FETCH: [
            {
              cond: 'itemIsAlreadyInCache',
              target: 'idle',
            },
            {
              target: 'fetching',
              actions: 'assignVariablesToContext',
            },
          ],
        },
        initial: 'noError',
        states: {
          noError: {
            entry: ['clearErrorMessage'],
          },
          errored: {},
        },
      },
      fetching: {
        on: {
          FETCH: [
            {
              cond: 'itemIsAlreadyInCache',
              target: 'idle',
            },
            {
              target: 'fetching',
              actions: 'assignVariablesToContext',
            },
          ],
          CANCEL: {
            target: 'idle',
          },
          RECEIVE_DATA: {
            target: 'idle',
            actions: ['assignDataToContext'],
          },
        },
        invoke: {
          src: 'fetchData',
          onError: {
            target: 'idle.errored',
            actions: 'assignErrorToContext',
          },
        },
      },
    },
  },
  {
    guards: {
      itemIsAlreadyInCache: (context, event) => {
        if (event.type !== 'FETCH') return false;

        return Boolean(context.cache[JSON.stringify(event.variables)]);
      },
    },
    services: {
      fetchData: () => () => {},
    },
    actions: {
      assignVariablesToContext: assign((context, event) => {
        if (event.type !== 'FETCH') return {};
        return {
          currentVariablesBeingProcessed: event.variables,
        };
      }),
      assignDataToContext: assign((context, event) => {
        if (event.type !== 'RECEIVE_DATA') return {};
        return {
          cache: {
            ...context.cache,
            [JSON.stringify(
              context.currentVariablesBeingProcessed,
            )]: event.data,
          },
        };
      }),
      clearErrorMessage: assign((context) => ({
        errorMessage: undefined,
      })),
      assignErrorToContext: assign((context, event: any) => {
        return {
          errorMessage: event.data?.message || 'An unknown error occurred',
        };
      }),
    },
  },
);

export default withLocalCacheMachine;

