export const ModalDialog: React.FC<
  OverlayProps & { title: string } & AriaDialogProps
> = (props) => {
  let { title, children } = props;

  let ref = React.useRef();
  let { overlayProps } = useOverlay(props, ref);

  usePreventScroll();
  let { modalProps } = useModal();

  let { dialogProps, titleProps } = useDialog(props, ref);

  return (
    <div
      style={{
        position: 'fixed',
        zIndex: 100,
        top: 0,
        left: 0,
        bottom: 0,
        right: 0,
        background: 'rgba(0, 0, 0, 0.5)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
      }}
    >
      <FocusScope contain restoreFocus autoFocus>
        <div {...overlayProps} {...dialogProps} {...modalProps} ref={ref}>
          <VisuallyHidden>
            <h3 {...titleProps} style={{ marginTop: 0 }}>
              {title}
            </h3>
          </VisuallyHidden>
          {children}
        </div>
      </FocusScope>
    </div>
  );
};

import { assign, createMachine, Interpreter, Sender } from 'xstate';

interface Context {
  searchModalText: string;
}

type Event =
  | {
      type: 'CMD_K_PRESSED';
    }
  | {
      type: 'CLICK_SEARCH';
    }
  | {
      type: 'UPDATE_SEARCH_MODAL_TEXT';
      text: string;
    }
  | {
      type: 'CLOSE';
    };

export type ModalsMachineInterpreter = Interpreter<Context, any, Event>;

export const modalsMachine = createMachine<Context, Event>(
  {
    initial: 'idle',
    context: {
      searchModalText: '',
    },
    states: {
      idle: {
        on: {
          CMD_K_PRESSED: {
            target: 'showingSearchModal',
          },
          CLICK_SEARCH: {
            target: 'showingSearchModal',
          },
        },
        invoke: {
          src: 'listenForKeyboardShortcuts',
        },
      },
      showingSearchModal: {
        on: {
          CLOSE: 'idle',
          UPDATE_SEARCH_MODAL_TEXT: {
            actions: assign((context, event) => {
              return {
                searchModalText: event.text,
              };
            }),
          },
        },
      },
    },
  },
  {
    services: {
      listenForKeyboardShortcuts: () => (send: Sender<Event>) => {
        const listener = (e: KeyboardEvent) => {
          if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
            e.preventDefault();
            send('CMD_K_PRESSED');
          }
        };
        document.addEventListener('keydown', listener);

        return () => {
          document.removeEventListener('keydown', listener);
        };
      },
    },
  },
);

interface UseCopyToClipboardParams {
  onSuccess?: (name: string) => void;
  onError?: (name: string) => void;
}

/**
 * Use this hook to return a function which copies a string
 * to the user's clipboard
 *
 * NOTE - does not work when in modals using a focus trap...
 */
export const useCopyToClipboard = ({
  onError,
  onSuccess,
}: UseCopyToClipboardParams) => {
  const copyToClipboard = (content: string) => {
    if (process.env.NODE_ENV === 'test') {
      onSuccess?.(content);
    } else {
      try {
        const dummyDiv = document.createElement('textarea');

        dummyDiv.value = content;

        document.body.appendChild(dummyDiv);

        dummyDiv.select();
        dummyDiv.setSelectionRange(0, 99999);

        document.execCommand('copy');
        document.body.removeChild(dummyDiv);

        onSuccess?.(content);
      } catch (e) {
        console.error(e);
        onError?.(content);
      }
    }
  };
  return copyToClipboard;
};

